"""Deterministic generator of the provider seed (MAM-50): writes testdata/seed/provider_db/01-providers.sql.

Synthetic data only (synthetic-data skill section 1): obviously fake names, NPIs with a valid check digit drawn from a
seeded random generator inside the 10059xxxxx block (never 1003000xxx or 1990000xxx, the journey applicants), and
licence numbers SD10001.. that the licence-board stub (MAM-47) must answer ACTIVE. Same seed, same file.

Run: python modern/testdata/generate_seed.py
"""
import random
import uuid
from pathlib import Path

SEED = 20260115                      # also the frozen business date 2026-01-15
HERE = Path(__file__).resolve().parent
OUT = HERE / "seed/provider_db/01-providers.sql"
NS = uuid.UUID("6d1c9d9e-5b3a-4c8e-9f57-2c1f0e5a0b50")   # fixed namespace for the seed's public ids

# (key, type, taxonomy, tier, status, flag, effective, end, reval_due, individual(first, last, licence) | org(legal, dba), owner_key)
PROVIDERS = [
    ("alpha",   "IN", "207Q00000X", "L", "A", "P", "2021-03-01", None,         "2030-06-01", ("TESTPROV", "ALPHA",   "SD10001"), None),
    ("bravo",   "IN", "225100000X", "M", "A", "P", "2021-01-15", None,         "2026-01-15", ("TESTPROV", "BRAVO",   "SD10002"), None),
    ("charlie", "IN", "207Q00000X", "L", "A", "P", "2020-12-01", None,         "2025-12-01", ("TESTPROV", "CHARLIE", "SD10003"), None),
    ("delta",   "IN", "207Q00000X", None, "P", "U", "2026-01-10", None,        None,         ("TESTPROV", "DELTA",   "SD10004"), None),
    ("echo",    "IN", "225100000X", None, "D", "F", "2025-11-01", None,         None,         ("TESTPROV", "ECHO",    "SD10005"), None),
    ("foxtrot", "IN", "207Q00000X", "L", "S", "P", "2022-05-01", None,         "2027-05-01", ("TESTPROV", "FOXTROT", "SD10006"), None),
    ("golf",    "IN", "207Q00000X", "L", "T", "P", "2019-02-01", "2025-06-30", "2024-02-01", ("TESTPROV", "GOLF",    "SD10007"), None),
    ("clinic",  "GR", "193200000X", "L", "A", "P", "2023-04-01", None,         "2028-04-01", ("SAMPLE CLINIC 01", "SAMPLE CLINIC GROUP 01"), "alpha"),
    ("hosp1",   "FA", "251G00000X", "H", "A", "P", "2021-02-15", None,         "2026-02-15", ("SAMPLE HOSPICE 01", "SAMPLE HOSPICE CARE 01"), "charlie"),
    ("hosp2",   "FA", "251G00000X", "H", "T", "P", "2020-03-01", "2025-09-30", "2025-03-01", ("SAMPLE HOSPICE 02", "SAMPLE HOSPICE CARE 02"), "golf"),
    ("dme",     "FA", "332B00000X", "H", "A", "P", "2024-08-01", None,         "2029-08-01", ("SAMPLE MEDICAL SUPPLY 01", "SAMPLE DME 01"), "bravo"),
    ("hha",     "FA", "251E00000X", None, "P", "U", "2026-01-12", None,        None,         ("SAMPLE HOME HEALTH 01", "SAMPLE HOME CARE 01"), "alpha"),
    ("amb",     "FA", "341600000X", "M", "A", "P", "2021-03-31", None,         "2026-03-31", ("SAMPLE AMBULANCE 01", "SAMPLE TRANSPORT 01"), "bravo"),
    ("lab",     "FA", "291U00000X", None, "D", "F", "2025-12-01", None,         None,         ("SAMPLE LAB 01", "SAMPLE LABORATORY 01"), "charlie"),
    ("hospital", "FA", "282N00000X", "L", "A", "P", "2025-01-01", None,        "2030-01-01", ("SAMPLE HOSPITAL 01", "SAMPLE MEDICAL CENTER 01"), "alpha"),
    ("therapy", "GR", "225100000X", "M", "S", "P", "2022-09-01", None,         "2027-09-01", ("SAMPLE THERAPY GROUP 01", "SAMPLE REHAB 01"), "bravo"),
]


def check_digit(first9: str) -> str:
    """NPI check digit: Luhn over 80840 + the first nine digits."""
    total = 0
    for i, ch in enumerate(reversed("80840" + first9)):
        d = int(ch)
        if i % 2 == 0:
            d = d * 2 - 9 if d * 2 > 9 else d * 2
        total += d
    return str((10 - total % 10) % 10)


def npis(rng: random.Random, n: int) -> list:
    out = []
    while len(out) < n:
        first9 = "10059" + f"{rng.randrange(10000):04d}"
        if first9 not in [x[:9] for x in out]:
            out.append(first9 + check_digit(first9))
    return out


def q(v):
    return "NULL" if v is None else "'" + v + "'"


def d(v):
    return "NULL" if v is None else f"DATE '{v}'"


def main():
    rng = random.Random(SEED)
    keys = [p[0] for p in PROVIDERS]
    npi = dict(zip(keys, npis(rng, len(keys))))
    mid = {k: "9" + f"{rng.randrange(10**8):08d}" for k in keys}
    rows = []
    for key, typ, tax, tier, status, flag, eff, end, due, names, owner in PROVIDERS:
        if typ == "IN":
            first, last, lic = names
            person = f"{q(last)}, {q(first)}, {q(lic)}, 'TX', NULL, NULL, NULL"
        else:
            legal, dba = names
            person = f"NULL, NULL, NULL, NULL, {q(legal)}, {q(dba)}, {q(npi[owner])}"
        rows.append(f"  ('{uuid.uuid5(NS, npi[key])}', '{npi[key]}', '{mid[key]}', '{typ}', '{tax}', {q(tier)}, '{status}', "
                    f"'{flag}', {d(eff)}, {d(end)}, {d(due)}, {person})")
    sql = (
        "-- MAM-50 provider seed. GENERATED by modern/testdata/generate_seed.py (seed 20260115); do not edit by hand.\n"
        "-- Restores exactly the seed state: empties provider_db's business tables (providers, owners, audit history and\n"
        "-- outbox; processed_event is kept), then inserts the seeded providers.\n"
        "-- make seed (infra/scripts/seed.sh) runs this file in one transaction, so a failure keeps the previous state.\n"
        "-- Synthetic data only: obviously fake names, NPIs with a valid check digit outside the journey ranges.\n"
        "TRUNCATE provider_owner, provider, audit_log, outbox_event RESTART IDENTITY;\n"
        "INSERT INTO provider (public_id, npi, medicaid_id, provider_type, taxonomy, risk_tier, enroll_status, screen_flag,\n"
        "  effective_date, end_date, reval_due_date, last_name, first_name, license_no, license_state, legal_name, dba_name,\n"
        "  owner_npi) VALUES\n" + ",\n".join(rows) + ";\n"
    )
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(sql, encoding="utf-8", newline="\n")
    write_service_seeds(npi, mid)
    for key in keys:
        print(f"{key:9s} {npi[key]} {mid[key]}")


# ---- MAM-51: the read models and histories of the other services, matching the provider seed ----------------------

HEADER = ("-- MAM-51 seed. GENERATED by modern/testdata/generate_seed.py (seed 20260115); do not edit by hand.\n"
          "-- Restores exactly the seed state of this database (one transaction, re-runnable); processed_event is kept.\n"
          "-- Synthetic data only, matching seed/provider_db/01-providers.sql.\n")
SOURCES = ["LICBOARD", "OIGLEIE", "SAMGOV", "SSADMF"]
# Denied providers with flag F: which source failed and why (synthetic findings, error codes of ERRCODES.cpy)
FAILED = {"echo": ("LICBOARD", "E202", "SD10005 EXPIRED 2025-10-31"),
          "lab": ("OIGLEIE", "E201", "EXCLUDED 1128A1 SINCE 2025-06-01")}
# Terminated and suspended providers: their sanction (action, effective date, reason)
SANCTIONS = {"golf": ("T", "2025-06-30", "SEEDED TERMINATION"),
             "hosp2": ("T", "2025-09-30", "SEEDED TERMINATION"),
             "foxtrot": ("S", "2025-10-01", "SEEDED SUSPENSION"),
             "therapy": ("S", "2025-10-01", "SEEDED SUSPENSION")}


def write(rel: str, sql: str):
    path = HERE / "seed" / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(sql, encoding="utf-8", newline="\n")


def display_name(typ, names):
    """D-028: first name + last name for an individual, the legal name otherwise (as directory-service composes it)."""
    return f"{names[0]} {names[1]}" if typ == "IN" else names[0]


def write_service_seeds(npi: dict, mid: dict):
    # AC-4: the directory read model holds every seeded provider; the public list shows only status A.
    rows = []
    for key, typ, tax, tier, status, flag, eff, end, due, names, owner in PROVIDERS:
        # MAM-65: the profile the FHIR resources show (names and licence of an individual, legal name otherwise)
        if typ == "IN":
            first, last, lic = names
            profile = f"{q(first)}, {q(last)}, NULL, {q(lic)}, 'TX'"
        else:
            profile = f"NULL, NULL, {q(names[0])}, NULL, NULL"
        rows.append(f"  ('{npi[key]}', '{mid[key]}', '{typ}', {q(tier)}, '{status}', {q(display_name(typ, names))}, '{tax}', "
                    f"{profile})")
    write("directory_db/02-directory.sql", HEADER
          + "-- AC-4: the directory read model of every seeded provider (published: status A only, MAM-63), with the\n"
          + "-- profile columns the FHIR resources show (MAM-65).\n"
          + "TRUNCATE directory_entry RESTART IDENTITY;\n"
          + "INSERT INTO directory_entry (npi, medicaid_id, provider_type, risk_tier, enroll_status, display_name, taxonomy,"
          + " first_name, last_name, legal_name, license_no, license_state)"
          + " VALUES\n" + ",\n".join(rows) + ";\n")

    # AC-2: one completed INITIAL screening with one result per source for every provider with flag P or F.
    screenings, results = [], []
    for key, typ, tax, tier, status, flag, eff, end, due, names, owner in PROVIDERS:
        if flag not in ("P", "F"):
            continue
        sid = uuid.uuid5(NS, "screening:" + npi[key])
        at = f"TIMESTAMPTZ '{eff} 10:00:00+00'"
        failed = FAILED.get(key)
        screenings.append(f"  ('{sid}', '{npi[key]}', 'INITIAL', 'COMPLETED', '{'FAIL' if failed else 'PASS'}', {at}, {at})")
        for source in SOURCES:
            if failed and failed[0] == source:
                res, code, detail = "F", f"'{failed[1]}'", failed[2]
            else:
                res, code, detail = "P", "NULL", "SEEDED: NO FINDING"
            results.append(f"  ((SELECT id FROM screening WHERE public_id = '{sid}'), '{source}', '{res}', {at}, "
                           f"'{detail}', {code})")
    write("screening_db/02-screenings.sql", HEADER
          + "-- AC-2: one completed screening per screened seeded provider (flag P: only P results; flag F: one F result).\n"
          + "TRUNCATE screening_result, screening, outbox_event RESTART IDENTITY;\n"
          + "INSERT INTO screening (public_id, npi, reason, status, result, started_at, completed_at) VALUES\n"
          + ",\n".join(screenings) + ";\n"
          + "INSERT INTO screening_result (screening_id, source, result, verdict_at, detail, error_code) VALUES\n"
          + ",\n".join(results) + ";\n")

    # AC-3: a sanction for every terminated (T) and suspended (S) seeded provider; nobody else has one (J5: ALPHA none).
    rows = []
    for key, (action, eff_date, reason) in SANCTIONS.items():
        rows.append(f"  ('{uuid.uuid5(NS, 'sanction:' + npi[key])}', '{npi[key]}', '{action}', '{reason}', DATE '{eff_date}', "
                    f"'supervisor1', '{action}', TIMESTAMPTZ '{eff_date} 09:00:00+00', TIMESTAMPTZ '{eff_date} 09:00:00+00')")
    write("sanctions_db/01-sanctions.sql", HEADER
          + "-- AC-3: the sanction history of the seeded terminated and suspended providers.\n"
          + "TRUNCATE sanction, sanction_intake_run, outbox_event RESTART IDENTITY;\n"
          + "INSERT INTO sanction (public_id, npi, action, reason, effective_date, recorded_by, resulting_status, created_at,"
          + " updated_at) VALUES\n" + ",\n".join(rows) + ";\n")

    # AC-5: the revalidation read model (status and due date of every seeded provider); no case and no run yet.
    rows = [f"  ('{npi[key]}', '{status}', {d(due)})"
            for key, typ, tax, tier, status, flag, eff, end, due, names, owner in PROVIDERS]
    write("revalidation_db/01-revalidation.sql", HEADER
          + "-- AC-5: revalidation-service's read model of the seeded providers, as ProviderStatusChanged would have left it.\n"
          + "TRUNCATE revalidation_case, sweep_run, tracked_provider, outbox_event RESTART IDENTITY;\n"
          + "INSERT INTO tracked_provider (npi, enroll_status, reval_due_date) VALUES\n" + ",\n".join(rows) + ";\n")


if __name__ == "__main__":
    main()
